/*
  Hand-drawn "boil": two positions, half a dash period apart, held 0.5s each.
  steps(2) samples progress at 0 and 0.5, so the -10 endpoint (one full
  --sketch-dash period, which would land back where it started) is never shown.
*/
@keyframes sketch-dash-boil {
  to {
    stroke-dashoffset: -10;
  }
}

/*
  Alternating dashes: with a 5/5 dasharray the period is 10, so sampling the
  -10 sweep at steps(2) swaps dash and gap positions on every other frame.
*/
@keyframes sketch-dash-alternate {
  to {
    stroke-dashoffset: -10;
  }
}

@keyframes sketch-icon-wiggle {
  0%,
  100% {
    transform: rotate(-5deg);
  }

  50% {
    transform: rotate(5deg);
  }
}

"use client";

import "./sketch.css";

import {
  type ReactNode,
  useContext,
  useId,
  useLayoutEffect,
  useMemo,
  useState,
} from "react";
import rough from "roughjs";
import {
  createRoundedRectanglePath,
  createSeed,
  createUnderlinePath,
  DEFAULT_SEED,
  DEFAULT_STROKE_WIDTH,
  getBorderRadius,
  getCssSketchOptions,
  getCssSketchSeed,
  getPaddingBoxSize,
  MIN_STROKE_WIDTH,
  SketchContext,
  type SketchOutline,
  type SketchOutlineOptions,
  type SketchScope,
  type SketchShape,
  type SketchTheme,
} from "./utils/sketch";

export type SketchProviderProps = {
  children: ReactNode;
  seed?: number;
};

export type { SketchOutline, SketchOutlineOptions, SketchScope, SketchShape } from "./utils/sketch";

export function SketchProvider({ children, seed = DEFAULT_SEED }: SketchProviderProps) {
  const value = useMemo(() => ({ seed }), [seed]);

  return <SketchContext.Provider value={value}>{children}</SketchContext.Provider>;
}


/**
 * Draws a RoughJS outline into an `<svg>` overlaying the parent element.
 *
 * @param options RoughJS options plus `shape`, `opacity`, and `id`.
 * `id` seeds the wobble and defaults to `useId()`. Because `useId()` shifts
 * with tree position, pass a stable `id` when the drawn geometry must not
 * change, such as shared shapes across instances or visual regression
 * snapshots.
 * @returns The `ref` and `style` to spread onto the outline `<svg>`.
 */
export function useSketchOutline(
  options: SketchOutlineOptions = {},
  scope: SketchScope = "outline",
): SketchOutline {
  const { id, opacity, shape = "rectangle", ...roughOptions } = options;
  const theme = useSketch();
  const [svg, setSvg] = useState<SVGSVGElement | null>(null);
  const fallbackId = useId();
  const instanceId = id ?? fallbackId;

  useLayoutEffect(() => {
    const target = svg?.parentElement;

    if (!svg || !target) {
      return;
    }

    let frame = 0;
    const draw = () => {
      const { height, width } = getPaddingBoxSize(target);

      if (width <= 0 || height <= 0) {
        return;
      }

      const drawing = rough.svg(svg);
      const drawingOptions = {
        ...getCssSketchOptions(target, scope),
        ...roughOptions,
        seed: createSeed(getCssSketchSeed(target, scope) ?? theme.seed, instanceId),
      };
      const strokeWidth = Math.max(
        MIN_STROKE_WIDTH,
        drawingOptions.strokeWidth ?? DEFAULT_STROKE_WIDTH,
      );
      const path = getSketchPath(shape, target, width, height, strokeWidth);
      const drawn = drawing.path(path, { ...drawingOptions, strokeWidth });

      svg.setAttribute("viewBox", `0 0 ${width} ${height}`);
      svg.replaceChildren(drawn);
    };

    const scheduleDraw = () => {
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(draw);
    };

    const observer = new ResizeObserver(scheduleDraw);
    observer.observe(target);
    const attributeObserver = new MutationObserver(scheduleDraw);
    attributeObserver.observe(target, {
      attributeFilter: ["class", "style"],
      attributes: true,
    });
    scheduleDraw();

    return () => {
      cancelAnimationFrame(frame);
      attributeObserver.disconnect();
      observer.disconnect();
    };
  }, [instanceId, scope, shape, svg, theme.seed]);

  return {
    ref: setSvg,
    style: {
      height: "100%",
      left: 0,
      opacity,
      // Rough's wobble swings past the viewBox; the default svg clip shaves it to a hairline.
      overflow: "visible",
      pointerEvents: "none",
      position: "absolute",
      top: 0,
      width: "100%",
    },
  };
}

export function useSketchBg(options: SketchOutlineOptions = {}): SketchOutline {
  return useSketchOutline(options, "bg");
}

function getSketchPath(
  shape: SketchShape,
  target: Element,
  width: number,
  height: number,
  strokeWidth: number,
): string {
  if (shape === "underline") {
    return createUnderlinePath(width, height, strokeWidth);
  }

  return createRoundedRectanglePath(width, height, getBorderRadius(target), strokeWidth);
}

function useSketch(): SketchTheme {
  const theme = useContext(SketchContext);

  if (theme === null) {
    throw new Error("Sketch components must be rendered inside SketchProvider.");
  }

  return theme;
}

import { createContext, type CSSProperties, type Ref } from "react";
import type { Options } from "roughjs/bin/core";

export const DEFAULT_SEED = 20_260_828;
export const DEFAULT_STROKE_WIDTH = 1.6;
export const MIN_STROKE_WIDTH = 1;

export type SketchTheme = {
	seed: number;
};

export const SketchContext = createContext<SketchTheme | null>(null);

export type SketchShape = "rectangle" | "underline";

export type SketchOutlineOptions = Omit<Partial<Options>, "seed"> & {
	borderRadius?: number;
	id?: string;
	opacity?: number;
	shape?: SketchShape;
};

export type SketchOutline = {
	ref: Ref<SVGSVGElement>;
	style: CSSProperties;
};

/**
 * Namespace for the `--sketch-*` custom properties a drawing reads.
 *
 * `"bg"` resolves `--sketch-bg-<name>` first and falls back to `--sketch-<name>`,
 * so a background inherits shared wobble settings while keeping its own fill.
 */
export type SketchScope = "outline" | "bg";

const CSS_NUMBER_OPTIONS = {
	bowing: "bowing",
	fillWeight: "fill-weight",
	hachureAngle: "hachure-angle",
	hachureGap: "hachure-gap",
	roughness: "roughness",
	strokeWidth: "stroke-width",
} as const;

const CSS_STRING_OPTIONS = {
	fill: "fill",
	fillStyle: "fill-style",
	stroke: "stroke",
} as const;

const CSS_BOOLEAN_OPTIONS = {
	disableMultiStroke: "disable-multi-stroke",
	preserveVertices: "preserve-vertices",
} as const;

export function createSeed(seed: number, instanceId: string): number {
	let hash = seed;

	for (let index = 0; index < instanceId.length; index += 1) {
		hash = (hash << 5) - hash + instanceId.charCodeAt(index);
		hash |= 0;
	}

	return (hash >>> 0) % 2_147_483_647 || 1;
}

export function getCssSketchOptions(
	target: Element,
	scope: SketchScope = "outline",
): Partial<Options> {
	const styles = getComputedStyle(target);
	const read = (name: string) => readScopedCssValue(styles, scope, name);
	const options: Record<string, unknown> = {};

	for (const [option, name] of Object.entries(CSS_NUMBER_OPTIONS)) {
		const value = Number.parseFloat(read(name));

		if (!Number.isNaN(value)) {
			options[option] = value;
		}
	}

	for (const [option, name] of Object.entries(CSS_STRING_OPTIONS)) {
		const value = read(name);

		if (value !== "") {
			options[option] = value;
		}
	}

	for (const [option, name] of Object.entries(CSS_BOOLEAN_OPTIONS)) {
		const value = read(name);

		if (value === "true" || value === "false") {
			options[option] = value === "true";
		}
	}

	return options as Partial<Options>;
}

export function getCssSketchSeed(
	target: Element,
	scope: SketchScope = "outline",
): number | undefined {
	/*
		The seed is read as a quoted string because CSS minifiers round bare
		numbers to six significant digits (20260828 ships as 20260800), which
		would change every wobble between dev and production. Bare numbers are
		still accepted for hand-written overrides that stay small.
	*/
	const raw = readScopedCssValue(getComputedStyle(target), scope, "seed").replace(
		/^["']|["']$/g,
		"",
	);
	const value = Number.parseFloat(raw);

	if (Number.isNaN(value)) {
		return undefined;
	}

	return value;
}

export function getBorderRadius(target: Element): number {
	return Number.parseFloat(getComputedStyle(target).borderTopLeftRadius) || 0;
}

export function getPaddingBoxSize(target: HTMLElement): { height: number; width: number } {
	const styles = getComputedStyle(target);

	return {
		height:
			target.offsetHeight -
			readPixels(styles.borderTopWidth) -
			readPixels(styles.borderBottomWidth),
		width:
			target.offsetWidth -
			readPixels(styles.borderLeftWidth) -
			readPixels(styles.borderRightWidth),
	};
}

function readPixels(value: string): number {
	return Number.parseFloat(value) || 0;
}

export function createRoundedRectanglePath(
	width: number,
	height: number,
	radius: number,
	strokeInset: number,
): string {
	const left = strokeInset;
	const top = strokeInset;
	const right = width - strokeInset;
	const bottom = height - strokeInset;
	const cornerRadius = Math.min(radius, (right - left) / 2, (bottom - top) / 2);

	if (cornerRadius === 0) {
		return `M ${left} ${top} H ${right} V ${bottom} H ${left} Z`;
	}

	return [
		`M ${left + cornerRadius} ${top}`,
		`H ${right - cornerRadius}`,
		`Q ${right} ${top} ${right} ${top + cornerRadius}`,
		`V ${bottom - cornerRadius}`,
		`Q ${right} ${bottom} ${right - cornerRadius} ${bottom}`,
		`H ${left + cornerRadius}`,
		`Q ${left} ${bottom} ${left} ${bottom - cornerRadius}`,
		`V ${top + cornerRadius}`,
		`Q ${left} ${top} ${left + cornerRadius} ${top}`,
		"Z",
	].join(" ");
}

export function createUnderlinePath(
	width: number,
	height: number,
	strokeInset: number,
): string {
	const bottom = height - strokeInset;

	return `M ${strokeInset} ${bottom} H ${width - strokeInset}`;
}

function readScopedCssValue(
	styles: CSSStyleDeclaration,
	scope: SketchScope,
	name: string,
): string {
	if (scope === "bg") {
		const scoped = styles.getPropertyValue(`--sketch-bg-${name}`).trim();

		if (scoped !== "") {
			return scoped;
		}
	}

	return styles.getPropertyValue(`--sketch-${name}`).trim();
}
